/**
 * El día de hoy del negocio, tal como va. Todo lo que dice "hoy" se cuenta desde la medianoche de APP_TIMEZONE y no la de UTC, que en Santo Domingo empieza a las 8 de la noche del día anterior. Lo único que no es del día es lo que se llama "ahora" (lo que está abierto en este momento) y el total de contactos.

 */
export interface AnalyticsSummary {
  /** El día del negocio que se está contando, tal cual ("2026-09-20"). Se manda como texto a propósito: como fecha completa viajaría convertido a medianoche UTC, que en el Caribe es todavía el día anterior.
   */
  day: string;
  /** Zona horaria con la que se decidió ese día. */
  timeZone: string;
  /** Ventas cerradas hoy, una por conversación como mucho. */
  salesClosedToday: number;
  /** Conversaciones en las que se cruzó algún mensaje hoy. */
  conversationsToday: number;
  /** De esas, las que empezaron hoy (sesión abierta hoy). */
  newConversationsToday: number;
  /** Abiertas o en cola ahora mismo, sean de hoy o de antes. */
  openConversations: number;
  /** Conversaciones donde hoy contestó un agente virtual. */
  botHandledToday: number;
  /** Minutos medios que esperó el cliente hoy por una respuesta. */
  avgResponseMinutes: number;
  /** Cuántas esperas entraron en esa media (0 = no hay media). */
  respondedToday: number;
  /** Mensajes que salieron hoy y no los rechazó el canal. */
  messagesSentToday: number;
  /** Mensajes que escribieron los clientes hoy. */
  messagesReceivedToday: number;
  newContactsToday: number;
  totalContacts: number;
  campaignsSentToday: number;
}

/**
 * El día de hoy por canal, con el mismo criterio que AnalyticsSummary.
 */
export interface ChannelStat {
  channel: string;
  conversations: number;
  messages: number;
  /** Ventas cerradas hoy en ese canal. */
  sales: number;
}

/**
 * Lo que hizo hoy cada quien — solo los que tuvieron actividad. El tiempo de respuesta sale de los mensajes reales de sus conversaciones.

 */
export interface AgentPerformance {
  agentId: number;
  agentName: string;
  /** `human` o `virtual`. */
  agentType: string;
  conversations: number;
  salesClosed: number;
  avgResponseMinutes: number;
  /** Esperas medidas; 0 significa que no hay tiempo que mostrar. */
  respondedCount: number;
}

/**
 * Un día del negocio (APP_TIMEZONE), no un día de UTC.
 */
export interface DailyVolume {
  /** El día, tal cual ("2026-09-20"). */
  date: string;
  conversations: number;
  messages: number;
  sales: number;
}

export interface ReportsSummary {
  conversations: number;
  resolved: number;
  /** Resolved conversations as a percentage of all conversations in the period (0-100). */
  resolutionRate: number;
  inboundMessages: number;
  /** Messages sent by human agents. */
  outboundMessages: number;
  /** Messages sent by virtual (AI) agents. */
  botMessages: number;
  /** Average minutes between a customer's first message and the first reply. */
  avgFirstResponseMinutes: number;
  medianFirstResponseMinutes: number;
  p90FirstResponseMinutes: number;
  p95FirstResponseMinutes: number;
  /** Average minutes from first inbound message to resolution across resolved conversations. */
  avgResolutionMinutes: number;
  medianResolutionMinutes: number;
  p95ResolutionMinutes: number;
  /** Average Handling Time — total active minutes of agent/bot work per conversation, approximated from message activity windows. */
  avgHandlingMinutes: number;
  avgMessagesPerConversation: number;
  /** Average number of alternating turns (customer ↔ team) per session. */
  avgTurnsPerSession: number;
  /** Contacts whose first-ever conversation started in this period. */
  newContacts: number;
  /** Contacts with at least one prior conversation before this period who also appear in it. */
  returningContacts: number;
  /** Share of returning contacts among reached contacts (0-100). */
  returningShare: number;
  botToHumanEscalations: number;
  /** Escalations as a share of conversations that received bot handling (0-100). */
  escalationRate: number;
  /** Times a human agent claimed a conversation via /claim. */
  takeovers: number;
  /** Takeovers as a share of all conversations in the period (0-100). */
  takeoverRate: number;
  /** Conversations whose session was reopened after being closed at least once. */
  reopenedConversations: number;
  /** Reopened conversations as a share of all conversations in the period (0-100). */
  reopenRate: number;
  activeAgents: number;
  contactsReached: number;
}

